     1→import notifee, {
     2→  AndroidImportance,
     3→  AndroidVisibility,
     4→  EventType,
     5→  type Notification,
     6→} from "@notifee/react-native";
     7→import { NavigationContainerRef } from "modules/navigation/const";
     8→
     9→type CreatePayload = {
    10→  message: string;
    11→  title?: string;
    12→  data?: Notification["data"];
    13→  id: string;
    14→};
    15→
    16→export class NotifeeService {
    17→  private static channelId = "local-push-notifications";
    18→
    19→  // Store pending room navigation for when app is opened from notification
    20→  // This is consumed by the Splash screen after session restoration
    21→  private static pendingRoomId: string | null = null;
    22→
    23→  public static init = async () => {
    24→    await notifee.createChannel({
    25→      id: "local-push-notifications",
    26→      name: "Local push notifications",
    27→      sound: "default",
    28→      importance: AndroidImportance.HIGH,
    29→      visibility: AndroidVisibility.PUBLIC,
    30→    });
    31→
    32→    // Handle notification press when app is in foreground
    33→    notifee.onForegroundEvent((event) => {
    34→      if (event.type === EventType.PRESS) {
    35→        this.handleNotificationPress(event.detail.notification, false);
    36→      }
    37→    });
    38→
    39→    notifee.onBackgroundEvent(async (event) => {
    40→      if (event.type === EventType.PRESS) {
    41→        this.handleNotificationPress(event.detail.notification, false);
    42→      }
    43→    });
    44→
    45→    // Check if app was opened from a notification (cold start)
    46→    const initialNotification = await notifee.getInitialNotification();
    47→    if (initialNotification?.notification) {
    48→      this.handleNotificationPress(initialNotification.notification, true);
    49→    }
    50→  };
    51→
    52→  /** Get and clear the pending room navigation (used by Splash screen) */
    53→  public static consumePendingRoomId = (): string | null => {
    54→    const roomId = this.pendingRoomId;
    55→    this.pendingRoomId = null;
    56→    return roomId;
    57→  };
    58→
    59→  private static handleNotificationPress = (
    60→    notification: Notification | undefined,
    61→    isInitialNotification: boolean,
    62→  ) => {
    63→    const roomId = notification?.data?.room_id;
    64→    if (!roomId || typeof roomId !== "string") return;
    65→
    66→    // For initial notification (cold start), store the room_id
    67→    // and let the Splash screen handle navigation after session restoration
    68→    if (isInitialNotification) {
    69→      this.pendingRoomId = roomId;
    70→      return;
    71→    }
    72→
    73→    // For foreground/background events (app already running), navigate directly to room
    74→    NavigationContainerRef.navigate("room", { roomId });
    75→  };
    76→
    77→  public static create = (payload: CreatePayload) =>
    78→    notifee.displayNotification({
    79→      android: {
    80→        pressAction: { id: "default" },
    81→        channelId: this.channelId,
    82→        autoCancel: true,
    83→        color: "#292929",
    84→      },
    85→      title: payload.title,
    86→      body: payload.message,
    87→      id: payload.id,
    88→      data: payload.data,
    89→    });
    90→}
    91→

