     1→import { useAtom, useAtomValue } from "jotai";
     2→import { MatrixAtoms } from "modules/matrix-client/jotai";
     3→import { MatrixService } from "modules/matrix-client/services/matrix-service";
     4→import { PushNotificationsAtoms } from "modules/push-notifications/jotai";
     5→import { PushNotificationsService } from "modules/push-notifications/service";
     6→import { type FC, useEffect } from "react";
     7→
     8→export const PushNotificationServiceController: FC = () => {
     9→  const permissions = useAtomValue(PushNotificationsAtoms.isPermitted);
    10→  const client = useAtomValue(MatrixAtoms.matrixClient);
    11→  const [token, setToken] = useAtom(PushNotificationsAtoms.token);
    12→
    13→  // Register notification listeners when permissions are granted
    14→  useEffect(() => {
    15→    if (!permissions) return;
    16→    PushNotificationsService.registerListeners().catch((e) => {
    17→      console.warn("Failed to register notification listeners:", e);
    18→    });
    19→  }, [permissions]);
    20→
    21→  // Get FCM token when permissions are granted
    22→  useEffect(() => {
    23→    if (!permissions || !!token) return;
