    10→export type PushRuleCondition = {
    11→  kind: string;
    12→  key?: string;
    13→  pattern?: string;
    14→  is?: string;
    15→};
    16→
    17→export type PushRule = {
    18→  rule_id: string;
    19→  default: boolean;
    20→  enabled: boolean;
    21→  conditions?: PushRuleCondition[];
    22→  actions: (PushRuleAction | string)[];
    23→  pattern?: string;
    24→};
    25→
    26→export type PushRuleset = {
    27→  global: {
    28→    override?: PushRule[];
    29→    content?: PushRule[];
    30→    room?: PushRule[];
    31→    sender?: PushRule[];
    32→    underride?: PushRule[];
    33→  };
    34→};
    35→
    36→export type NotificationLevel = "all" | "mentions" | "none";
    37→
    38→/**
    39→ * Service for managing Matrix Push Rules
    40→ * Push rules determine when notifications should be sent to the user
    41→ */
    42→export const PushRulesService = {
    43→  /** Get all push rules for the current user */
    44→  getPushRules: async (): Promise<PushRuleset | null> => {
    45→    if (!MatrixService.instance) throw new Error("Client not initialized");
    46→
    47→    const session = MatrixService.instance.session();
    48→    if (!session) throw new Error("No active session");
    49→
    50→    try {
    51→      const response = await fetch(
    52→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_GET}`,
    53→        {
    54→          method: "GET",
    55→          headers: {
    56→            "Content-Type": "application/json",
    57→            Authorization: `Bearer ${session.accessToken}`,
    58→          },
    59→        },
    60→      );
    61→
    62→      if (!response.ok) {
    63→        console.error("Failed to get push rules:", response.status);
    64→        return null;
    65→      }
    66→
    67→      return await response.json();
    68→    } catch (error) {
    69→      console.error("Failed to fetch push rules:", error);
    70→      return null;
    71→    }
    72→  },
    73→
    74→  /** Enable or disable a specific push rule */
    75→  setRuleEnabled: async (
    76→    scope: string,
    77→    kind: string,
    78→    ruleId: string,
    79→    enabled: boolean,
    80→  ): Promise<boolean> => {
    81→    if (!MatrixService.instance) throw new Error("Client not initialized");
    82→
    83→    const session = MatrixService.instance.session();
    84→    if (!session) throw new Error("No active session");
    85→
    86→    try {
    87→      const response = await fetch(
    88→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_ENABLE}${scope}/${kind}/${ruleId}/enabled`,
    89→        {
    90→          method: "PUT",
    91→          headers: {
    92→            "Content-Type": "application/json",
    93→            Authorization: `Bearer ${session.accessToken}`,
    94→          },
    95→          body: JSON.stringify({ enabled }),
    96→        },
    97→      );
    98→
    99→      return response.ok;
   100→    } catch (error) {
   101→      console.error("Failed to set rule enabled state:", error);
   102→      return false;
   103→    }
   104→  },
   105→
   106→  /** Set actions for a specific push rule */
   107→  setRuleActions: async (
   108→    scope: string,
   109→    kind: string,
   110→    ruleId: string,
   111→    actions: (PushRuleAction | string)[],
   112→  ): Promise<boolean> => {
   113→    if (!MatrixService.instance) throw new Error("Client not initialized");
   114→
   115→    const session = MatrixService.instance.session();
   116→    if (!session) throw new Error("No active session");
   117→
   118→    try {
   119→      const response = await fetch(
   120→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSH_RULES_SET}${scope}/${kind}/${ruleId}/actions`,
   121→        {
   122→          method: "PUT",
   123→          headers: {
   124→            "Content-Type": "application/json",
   125→            Authorization: `Bearer ${session.accessToken}`,
   126→          },
   127→          body: JSON.stringify({ actions }),
   128→        },
   129→      );
   130→
   131→      return response.ok;
   132→    } catch (error) {
   133→      console.error("Failed to set rule actions:", error);
   134→      return false;
   135→    }
   136→  },
   137→
   138→  /**
   139→   * Configure notifications for group chats (rooms with >2 members)
   140→   * Uses the .m.rule.room_one_to_one underride rule
   141→   */
   142→  setGroupChatNotifications: async (
   143→    level: NotificationLevel,
   144→  ): Promise<boolean> => {
   145→    // For group chats, we modify the underride rule that matches rooms with more than 2 members
   146→    // The default rule is ".m.rule.message" which notifies for all messages
   147→    // We need to disable it for "mentions" or "none"
   148→
   149→    if (level === "none") {
   150→      // Disable notifications for group chats
   151→      return await PushRulesService.setRuleEnabled(
   152→        "global",
   153→        "underride",
   154→        ".m.rule.message",
   155→        false,
   156→      );
   157→    } else if (level === "mentions") {
   158→      // For mentions only, disable the general message rule
   159→      // but keep the mention rules enabled (they're in override/content)
   160→      return await PushRulesService.setRuleEnabled(
   161→        "global",
   162→        "underride",
   163→        ".m.rule.message",
   164→        false,
   165→      );
   166→    } else {
   167→      // For "all", enable the message rule
   168→      return await PushRulesService.setRuleEnabled(
   169→        "global",
   170→        "underride",
   171→        ".m.rule.message",
   172→        true,
   173→      );
   174→    }
   175→  },
   176→
   177→  /**
   178→   * Configure notifications for direct chats (1:1 rooms)
   179→   * Uses the .m.rule.room_one_to_one underride rule
   180→   */
   181→  setDirectChatNotifications: async (
   182→    level: NotificationLevel,
   183→  ): Promise<boolean> => {
   184→    const actions = getActionsForLevel(level);
   185→
   186→    if (level === "none") {
   187→      return await PushRulesService.setRuleEnabled(
   188→        "global",
   189→        "underride",
   190→        ".m.rule.room_one_to_one",
   191→        false,
   192→      );
   193→    } else if (level === "mentions") {
   194→      // For direct chats, "mentions" doesn't make much sense, but we'll keep the rule enabled
   195→      // with notify actions (all messages in DMs are somewhat like mentions)
   196→      return await PushRulesService.setRuleActions(
   197→        "global",
   198→        "underride",
   199→        ".m.rule.room_one_to_one",
   200→        actions,
   201→      );
   202→    } else {
   203→      // Enable and set actions for all messages
   204→      const enabled = await PushRulesService.setRuleEnabled(
   205→        "global",
   206→        "underride",
   207→        ".m.rule.room_one_to_one",
   208→        true,
   209→      );
   210→      if (!enabled) return false;
   211→
   212→      return await PushRulesService.setRuleActions(
   213→        "global",
   214→        "underride",
   215→        ".m.rule.room_one_to_one",
   216→        actions,
   217→      );
   218→    }
   219→  },
   220→
   221→  /**
   222→   * Configure notifications for mentions (@username or @room)
   223→   * Uses both newer override rules and older content rules for compatibility
   224→   */
   225→  setMentionsEnabled: async (enabled: boolean): Promise<boolean> => {
   226→    // Newer Matrix spec uses override rules
   227→    const overrideRules = [
   228→      ".m.rule.is_user_mention", // New: Matches @username mentions
   229→      ".m.rule.contains_display_name", // Matches display name
   230→      ".m.rule.is_room_mention", // New: Matches @room mentions
   231→      ".m.rule.roomnotif", // Old: Matches @room
   232→    ];
   233→
   234→    // Older Matrix spec uses content rules
   235→    const contentRules = [
   236→      ".m.rule.contains_user_name", // Old: Matches @username
   237→    ];
   238→
   239→    const overrideResults = await Promise.all(
   240→      overrideRules.map((ruleId) =>
   241→        PushRulesService.setRuleEnabled("global", "override", ruleId, enabled),
   242→      ),
   243→    );
   244→
   245→    const contentResults = await Promise.all(
   246→      contentRules.map((ruleId) =>
   247→        PushRulesService.setRuleEnabled("global", "content", ruleId, enabled),
   248→      ),
   249→    );
   250→
   251→    return [...overrideResults, ...contentResults].every((r) => r);
   252→  },
   253→
   254→  /**
   255→   * Configure notifications for room invitations
   256→   * Uses the .m.rule.invite_for_me override rule
   257→   */
   258→  setInvitationsEnabled: async (enabled: boolean): Promise<boolean> => {
   259→    return await PushRulesService.setRuleEnabled(
   260→      "global",
   261→      "override",
   262→      ".m.rule.invite_for_me",
   263→      enabled,
   264→    );
   265→  },
   266→
   267→  /** Get current notification settings from push rules */
   268→  getNotificationSettings: async (): Promise<{
   269→    groupChats: NotificationLevel;
   270→    directChats: NotificationLevel;
   271→    mentions: boolean;
   272→    invitations: boolean;
   273→  } | null> => {
   274→    const rules = await PushRulesService.getPushRules();
   275→
   276→    if (!rules || !rules.global) return null;
   277→
   278→    // Determine group chat level
   279→    const messageRule = rules.global.underride?.find(
   280→      (r) => r.rule_id === ".m.rule.message",
   281→    );
   282→    const groupChats: NotificationLevel = messageRule?.enabled
   283→      ? "all"
   284→      : "mentions";
   285→
   286→    // Determine direct chat level
   287→    const dmRule = rules.global.underride?.find(
   288→      (r) => r.rule_id === ".m.rule.room_one_to_one",
   289→    );
   290→    const directChats: NotificationLevel = dmRule?.enabled ? "all" : "none";
   291→
   292→    // Determine mentions - check both new and old rules
   293→    const newMentionRule = rules.global.override?.find(
   294→      (r) => r.rule_id === ".m.rule.is_user_mention",
   295→    );
   296→    const oldMentionRule = rules.global.content?.find(
   297→      (r) => r.rule_id === ".m.rule.contains_user_name",
   298→    );
   299→    const displayNameRule = rules.global.override?.find(
   300→      (r) => r.rule_id === ".m.rule.contains_display_name",
   301→    );
   302→
   303→    // Mentions are enabled if any of the mention rules are enabled
   304→    const mentions =
   305→      (newMentionRule?.enabled ?? false) ||
   306→      (oldMentionRule?.enabled ?? false) ||
   307→      (displayNameRule?.enabled ?? true);
   308→
   309→    // Determine invitations - check override section (not underride)
   310→    const inviteRule = rules.global.override?.find(
   311→      (r) => r.rule_id === ".m.rule.invite_for_me",
   312→    );
   313→    const invitations = inviteRule?.enabled ?? true;
   314→
   315→    return {
   316→      groupChats,
   317→      directChats,
   318→      mentions,
   319→      invitations,
   320→    };
   321→  },
   322→};
   323→
   324→/** Helper function to get actions array for a notification level */
   325→function getActionsForLevel(
   326→  level: NotificationLevel,
   327→): (PushRuleAction | string)[] {
   328→  switch (level) {
   329→    case "all":
   330→      return [
   331→        "notify",
   332→        { set_tweak: "sound", value: "default" },
   333→        { set_tweak: "highlight", value: false },
   334→      ];
   335→    case "mentions":
   336→      return [
   337→        "notify",
   338→        { set_tweak: "sound", value: "default" },
   339→        { set_tweak: "highlight", value: true },
   340→      ];
   341→    case "none":
   342→      return ["dont_notify"];
   343→  }
   344→}
