   149→      setTimeout(() => {
   150→        NavigationContainerRef.navigate("elementCall", {
   151→          roomId: callInfo.roomId,
   152→          roomName: callInfo.roomName,
   153→        });
   154→      }, 800);
   155→
   156→      this.activeCallMap.delete(callUUID);
   157→    });
   158→
   159→    // User declined the call from CallKit UI (or call ended by us after answer)
   160→    RNCallKeep.addEventListener("endCall", ({ callUUID }) => {
   161→      // If we ended this call ourselves (after answering), just clean up the flag
   162→      if (this.selfEndingCalls.has(callUUID)) {
   163→        this.selfEndingCalls.delete(callUUID);
   164→        return;
   165→      }
   166→
   167→      const callInfo = this.activeCallMap.get(callUUID);
   168→      if (!callInfo) return;
   169→
   170→      // Clear ring timeout
   171→      const timeout = this.ringTimeouts.get(callUUID);
   172→      if (timeout) {
   173→        clearTimeout(timeout);
   174→        this.ringTimeouts.delete(callUUID);
   175→      }
   176→
   177→      this.activeCallMap.delete(callUUID);
   178→    });
   179→
   180→    // User tapped a call entry in iPhone's Phone recents to call back
   181→    RNCallKeep.addEventListener(
   182→      "didReceiveStartCallAction",
