     9→/** Provider that initializes CallKit on iOS and monitors rooms for incoming calls via sync. */
    10→export const CallKitProvider = () => {
    11→  const roomList = useAtomValue(MatrixAtoms.roomList);
    12→  const prevActiveCallRoomIds = useRef<Set<string>>(new Set());
    13→
    14→  // Initialize CallKit
    15→  useEffect(() => {
    16→    if (Platform.OS !== "ios") return;
    17→
    18→    CallKitService.setup();
    19→  }, []);
    20→
    21→  // Monitor room list for active calls (foreground detection without push)
    22→  useEffect(() => {
    23→    if (Platform.OS !== "ios" || roomList.length === 0) return;
    24→
    25→    const currentActiveCallRoomIds = new Set<string>();
    26→
    27→    for (const room of roomList) {
    28→      if (!room.hasActiveRoomCall()) return;
    29→      currentActiveCallRoomIds.add(room.id());
    30→    }
    31→
    32→    // Detect newly active calls (rooms that weren't active before)
    33→    for (const roomId of currentActiveCallRoomIds) {
    34→      if (prevActiveCallRoomIds.current.has(roomId)) continue;
    35→
    36→      // Don't show CallKit if we initiated the call ourselves
    37→      if (ElementCallService.getActiveCallRoomId() === roomId) continue;
    38→
    39→      // Don't show if already ringing for this room (e.g. from push)
    40→      if (CallKitService.isRingingForRoom(roomId)) continue;
    41→
    42→      // Get room info for display
    43→      const roomInfo = MatrixService.getRoomInfo(roomId);
    44→      const roomName = roomInfo?.displayName() ?? "Unknown Room";
    45→      const currentUserId = MatrixService.instance?.userId();
    46→
    47→      // Don't ring for own calls
    48→      if (!currentUserId) continue;
    49→
    50→      CallKitService.displayIncomingCall({
    51→        roomId,
    52→        roomName,
    53→        senderDisplayName: roomName,
    54→      });
    55→    }
    56→
    57→    prevActiveCallRoomIds.current = currentActiveCallRoomIds;
    58→  }, [roomList]);
    59→
    60→  return <></>;
    61→};
